// Author: MiYu. Port the source-backed MEngine cliff/ramp topology to native Warcraft coordinates.
#include "terrain_scene.h"
#include "model.h"
#include <cmath>
#include <numeric>

namespace war3 {
TerrainChunk& TerrainScene::chunk(unsigned x,unsigned y,const std::string& texture,bool water) {auto key=std::make_tuple(x/16,y/16,texture,water);auto found=lookup_.find(key);if(found==lookup_.end()){if(chunks_.size()>=8192)throw std::runtime_error("Terrain chunk count exceeds budget");auto index=chunks_.size();TerrainChunk value;value.texture=texture;value.water=water;chunks_.push_back(std::move(value));found=lookup_.emplace(std::move(key),index).first;}return chunks_[found->second];}
void TerrainScene::append(TerrainChunk& target,std::span<const SceneVertex> vertices,std::span<const std::uint32_t> indices) {if(target.vertices.size()+vertices.size()>1000000 || target.indices.size()+indices.size()>3000000)throw std::runtime_error("Terrain chunk exceeds mesh budget");auto bytes=vertices.size()*sizeof(SceneVertex)+indices.size()*4;if(bytes>256*1024*1024-meshBytes_)throw std::runtime_error("Terrain mesh memory budget exceeded");meshBytes_+=bytes;auto start=unsigned(target.vertices.size());for(auto& v:vertices){target.vertices.push_back(v);target.bounds.add(v.x,v.y,v.z);}for(auto i:indices){if(i>=vertices.size())throw std::runtime_error("Terrain mesh index exceeds vertices");target.indices.push_back(start+i);}}
float TerrainScene::relief(const std::vector<float>& heights,float x,float y) const {auto w=source_.width,h=source_.height;x=std::clamp(x,0.f,float(w-1));y=std::clamp(y,0.f,float(h-1));auto ix=std::min(unsigned(x),w-2),iy=std::min(unsigned(y),h-2);float u=x-ix,v=y-iy;auto at=iy*w+ix;return (heights[at]*(1-u)+heights[at+1]*u)*(1-v)+(heights[at+w]*(1-u)+heights[at+w+1]*u)*v;}
std::vector<TerrainCell> TerrainScene::layout(const std::vector<TerrainCliff>& definitions,Log& log) {
    auto w=source_.width,h=source_.height,cw=w-1,ch=h-1;
    ground_.reserve(size_t(w)*h);surface_.reserve(size_t(w)*h);for(auto& c:source_.corners){auto value=(float(c.ground)-8192)/4;ground_.push_back(value);surface_.push_back(value+(int(c.cliff&15)-2)*128);}
    std::vector<bool> occupied(size_t(cw)*ch),entrances(occupied.size()),raised(size_t(w)*h);std::vector<int> cliffSkin(occupied.size(),-1);
    auto ids=[&](unsigned x,unsigned y){return std::array<unsigned,4>{y*w+x,(y+1)*w+x,(y+1)*w+x+1,y*w+x+1};};
    auto layers=[&](auto corners){std::array<unsigned,4> result{};for(unsigned i=0;i<4;++i)result[i]=source_.corners[corners[i]].cliff&15;return result;};
    for(unsigned y=0;y<ch;++y)for(unsigned x=0;x<cw;++x){auto corners=ids(x,y),v=layers(corners);auto base=*std::min_element(v.begin(),v.end());bool ramp=std::all_of(corners.begin(),corners.end(),[&](auto i){return (source_.corners[i].flags&0x10)!=0;});if(ramp && !(v[0]==v[2] && v[1]==v[3])){entrances[y*cw+x]=true;for(unsigned i=0;i<4;++i)if(v[i]==base)raised[corners[i]]=true;}}
    for(size_t i=0;i<raised.size();++i)if(raised[i])surface_[i]+=64;
    struct Template {ModelGeometry geometry;unsigned sx,sy;};std::map<std::string,std::optional<Template>> templates;
    auto resolve=[&](const std::string& family,const std::string& pattern,unsigned variation)->const Template* {
        const Template* last=nullptr;for(unsigned i=0;i<=variation;++i){assets_.check();auto member="Doodads\\Terrain\\"+family+"\\"+family+pattern+std::to_string(i)+".mdx";auto found=templates.find(member);if(found==templates.end()){std::optional<Template> value;if(assets_.resources().read(member)){auto geometry=assets_.model(member,log).geometry();SceneBounds bounds;for(auto& v:geometry.vertices)bounds.add(v.x,v.y,v.z);unsigned sx=unsigned(std::lround((bounds.high[0]-bounds.low[0])/128)),sy=unsigned(std::lround((bounds.high[1]-bounds.low[1])/128));if(!((sx==1 && sy==1)||(sx==1 && sy==2)||(sx==2 && sy==1)))throw std::runtime_error("Unsupported source cliff footprint: "+member);value=Template{std::move(geometry),sx,sy};}found=templates.emplace(std::move(member),std::move(value)).first;}if(!found->second)break;last=&*found->second;}return last;
    };
    auto skin=[&](unsigned x,unsigned y){auto value=source_.corners[y*w+x].cliff>>4;unsigned slot=value==15?1:unsigned(value);if(slot>=definitions.size())throw std::runtime_error("Cliff texture outside map tileset");return slot;};
    auto place=[&](const Template& model,unsigned x,unsigned y,int left,int bottom,unsigned base,unsigned texture){if(left<0 || bottom<0 || left+model.sx>cw || bottom+model.sy>ch)throw std::runtime_error("Cliff footprint leaves terrain");for(unsigned dy=0;dy<model.sy;++dy)for(unsigned dx=0;dx<model.sx;++dx){auto i=(bottom+dy)*cw+left+dx;if(occupied[i])throw std::runtime_error("Overlapping source cliff footprints");occupied[i]=true;cliffSkin[i]=int(texture);}std::vector<SceneVertex> vertices;vertices.reserve(model.geometry.vertices.size());for(auto& p:model.geometry.vertices){float gx=left+model.sx+p.x/128,gy=bottom+p.y/128;vertices.push_back({source_.origin[0]+gx*128,source_.origin[1]+gy*128,p.z+(int(base)-2)*128+relief(ground_,gx,gy),0xffffffff,p.u,p.v});}std::vector<std::uint32_t> indices(model.geometry.indices.begin(),model.geometry.indices.end());append(chunk(x,y,definitions[texture].texture),vertices,indices);};
    for(unsigned y=0;y<ch;++y){assets_.check();for(unsigned x=0;x<cw;++x){auto corners=ids(x,y),v=layers(corners);auto [min,max]=std::minmax_element(v.begin(),v.end());if(entrances[y*cw+x] || *max-*min!=1)continue;std::array<bool,4> marked;unsigned count=0;for(unsigned i=0;i<4;++i){marked[i]=(source_.corners[corners[i]].flags&0x10)!=0;count+=marked[i];}if(count!=2 || !((marked[0]!=marked[3] && marked[1]!=marked[2])||(marked[0]!=marked[1] && marked[3]!=marked[2])))continue;unsigned texture=skin(x,y);std::string pattern;for(unsigned i=0;i<4;++i)pattern+=marked[i]?(v[i]==*min?'L':'H'):char('A'+v[i]-*min);auto model=resolve(definitions[texture].ramp,pattern,0);if(!model)continue;int left=int(x),bottom=int(y),ex=int(x),ey=int(y);if(model->sx==2){if(v[0]+v[1]<v[2]+v[3])--left;ex=left<int(x)?left:int(x)+1;}else if(model->sy==2){if(v[0]+v[3]<v[1]+v[2])--bottom;ey=bottom<int(y)?bottom:int(y)+1;}else throw std::runtime_error("Ramp transition requires two cells");if(ex>=0 && ey>=0 && unsigned(ex)<cw && unsigned(ey)<ch){auto extra=layers(ids(unsigned(ex),unsigned(ey)));if(!std::all_of(extra.begin(),extra.end(),[&](auto n){return n==extra[0];}))continue;}place(*model,x,y,left,bottom,*min,texture);}}
    for(unsigned y=0;y<ch;++y){assets_.check();for(unsigned x=0;x<cw;++x){auto v=layers(ids(x,y));auto [min,max]=std::minmax_element(v.begin(),v.end());if(occupied[y*cw+x] || entrances[y*cw+x] || *min==*max)continue;unsigned texture=skin(x,y);std::string pattern;for(auto n:v)pattern+=char('A'+n-*min);auto model=resolve(definitions[texture].family,pattern,source_.corners[y*w+x].variation>>5);if(!model || model->sx!=1 || model->sy!=1)throw std::runtime_error("Unsupported cliff template at "+std::to_string(x)+","+std::to_string(y));place(*model,x,y,int(x),int(y),*min,texture);}}
    std::vector<unsigned> textures(size_t(w)*h);std::vector<bool> blightable(size_t(w)*h,true);for(unsigned y=0;y<h;++y)for(unsigned x=0;x<w;++x){auto& c=source_.corners[y*w+x];unsigned texture=c.flags&15;bool found=false;for(unsigned cy=y?y-1:0;cy<=std::min(y,ch-1) && !found;++cy)for(unsigned cx=x?x-1:0;cx<=std::min(x,cw-1);++cx){auto slot=cliffSkin[cy*cw+cx];if(slot>=0){blightable[y*w+x]=false;auto id=definitions[slot].ground;auto at=std::find(source_.groundTiles.begin(),source_.groundTiles.end(),id);texture=at==source_.groundTiles.end()?0:unsigned(at-source_.groundTiles.begin());found=true;break;}}if(texture>=source_.groundTiles.size())throw std::runtime_error("Ground texture outside map tileset");textures[y*w+x]=texture;}
    std::vector<TerrainCell> ground;ground.reserve(occupied.size());for(unsigned y=0;y<ch;++y)for(unsigned x=0;x<cw;++x)if(!occupied[y*cw+x]){auto corners=ids(x,y);std::array<unsigned,4> slots;for(unsigned i=0;i<4;++i)slots[i]=textures[corners[i]];std::array<bool,4> enabled;for(unsigned i=0;i<4;++i)enabled[i]=blightable[corners[i]];ground.push_back({corners,slots,x,y,unsigned(source_.corners[y*w+x].variation&31),enabled});}return ground;
}
}
